const today = new Date().toISOString().slice(0,10);
const MAP = {180:'inspire',150:'inspire',120:'inspire',90:'trousseau',60:'booking',30:'ratelock',7:'support','-15':'after'};
const out = [];
for (const it of items) {
  const r = it.json; if (!r.WeddingDate || !r.Phone) continue;
  const d = Math.round((new Date(r.WeddingDate) - new Date(today)) / 864e5);
  const key = Object.keys(MAP).find(k => Number(k) === d);
  if (!key) continue;
  if (r.LastTouch === today) continue;
  out.push({ json: { ...r, days: d, touch: MAP[key] } });
}
return out;
